function guardarPreferencias(prefs) {
  try {
    localStorage.setItem('preferencias', JSON.stringify(prefs));
  } catch (erro) {
    console.error('Nao foi possivel guardar preferencias:', erro);
  }
}

function lerPreferencias() {
  const dados = localStorage.getItem('preferencias');
  return dados === null ? {} : JSON.parse(dados);
}

