function registarVisita() {
  const valorGuardado = localStorage.getItem('visitas');
  const visitasAtuais = valorGuardado === null ? 0 : Number(valorGuardado);
  const novasVisitas = visitasAtuais + 1;
  localStorage.setItem('visitas', String(novasVisitas));
  return novasVisitas;
}

