function iniciarContagemDecrescente(segundos, aoCadaSegundo, aoTerminar) {
  let restante = segundos;

  const idIntervalo = setInterval(() => {
    restante -= 1;

    if (restante <= 0) {
      clearInterval(idIntervalo);
      aoTerminar();
      return;
    }

    aoCadaSegundo(restante);
  }, 1000);

  return function cancelar() {
    clearInterval(idIntervalo);
  };
}

const cancelar = iniciarContagemDecrescente(
  5,
  (restante) => console.log(`Faltam ${restante} segundos`),
  () => console.log('Tempo esgotado!')
);

