const carrinho = {
  cliente: 'Ana',
  itens: [
    { nome: 'Teclado', preco: 45.9, quantidade: 1 },
    { nome: 'Rato', preco: 19.5, quantidade: 2 }
  ],
  criadoEm: new Date()
};

function aplicarDesconto(carrinhoOriginal, percentagem) {
  const copia = structuredClone(carrinhoOriginal);

  copia.itens.forEach((item) => {
    item.preco = item.preco * (1 - percentagem / 100);
  });

  const total = copia.itens.reduce(
    (soma, item) => soma + item.preco * item.quantidade,
    0
  );

  const formatadorMoeda = new Intl.NumberFormat('pt-PT', {
    style: 'currency',
    currency: 'EUR'
  });

  return {
    carrinho: copia,
    totalFormatado: formatadorMoeda.format(total)
  };
}

const resultado = aplicarDesconto(carrinho, 10);
console.log(resultado.totalFormatado);
console.log(carrinho.itens[0].preco); // 45.9, o original nao foi alterado
